+instruct string_indexofLL_sve(iRegP_R1 str1, iRegI_R4 cnt1, iRegP_R3 str2, iRegI_R2 cnt2,
+                              iRegI_R0 result, iRegINoSp tmp1, iRegINoSp tmp2, iRegINoSp tmp3,
+                              iRegINoSp tmp4, iRegINoSp tmp5, iRegINoSp tmp6, iRegINoSp tmp7, iRegINoSp tmp8,
+                              vRegD_V0 vtmp1, vRegD_V1 vtmp2, vRegD vtmp3, vRegD vtmp4, vRegD vtmp5,
+                              pRegGov ptmp1, pRegGov ptmp2, pRegGov ptmp3, pRegGov ptmp4, pRegGov ptmp5, rFlagsReg cr)
+%{
+  predicate((((StrIndexOfNode*)n)->encoding() == StrIntrinsicNode::LL) && UseSVE > 0);
+  match(Set result (StrIndexOf (Binary str1 cnt1) (Binary str2 cnt2)));
+  effect(USE_KILL str1, USE_KILL str2, USE_KILL cnt1, USE_KILL cnt2,
+         TEMP tmp1,  TEMP tmp2,  TEMP tmp3,  TEMP tmp4,  TEMP tmp5, TEMP tmp6, TEMP tmp7, TEMP tmp8,
+         TEMP vtmp1, TEMP vtmp2, TEMP vtmp3, TEMP vtmp4, TEMP vtmp5,
+         TEMP ptmp1, TEMP ptmp2, TEMP ptmp3, TEMP ptmp4, TEMP ptmp5,
+         KILL cr);
+  format %{ "String IndexOf (SVE) $str1,$cnt1,$str2,$cnt2 -> $result (LL) "
+            "# KILL $str1 $cnt1 $str2 $cnt2 $tmp1 $tmp2 $tmp3 $tmp4 $tmp5 $tmp6 $tmp7 $tmp8 $vtmp1 $vtmp2 $vtmp3 $vtmp4 $vtmp5 $ptmp1 $ptmp2 $ptmp3 $ptmp4 $ptmp5 cr" %}
+  ins_encode %{
+    __ string_indexof_sve($str1$$Register, $str2$$Register,
+                          $cnt1$$Register, $cnt2$$Register,
+                          $tmp1$$Register, $tmp2$$Register,
+                          $tmp3$$Register, $tmp4$$Register,
+                          $tmp5$$Register, $tmp6$$Register,
+                          $tmp7$$Register, $tmp8$$Register,
+                          $vtmp1$$FloatRegister, $vtmp2$$FloatRegister,
+                          $vtmp3$$FloatRegister, $vtmp4$$FloatRegister,
+                          $vtmp5$$FloatRegister,
+                          $ptmp1$$PRegister, $ptmp2$$PRegister,
+                          $ptmp3$$PRegister, $ptmp4$$PRegister,
+                          $ptmp5$$PRegister,
+                          $result$$Register, StrIntrinsicNode::LL);
+  %}
+  ins_pipe(pipe_class_memory);
+%}
